   Click("WatchRules",ToggleWatch);
   watchTimer=new DispatcherTimer {Interval=TimeSpan.FromSeconds(8)};watchTimer.Tick+=(s,e)=>WatchTick();
   Click("LoadApps",LoadApps);Click("OpenAppFolder",()=>{var app=Find<DataGrid>("AppList").SelectedItem as InstalledApp;if(app!=null&&!String.IsNullOrWhiteSpace(app.Location)&&Directory.Exists(app.Location))OpenFolder(app.Location);else Error("Ứng dụng này không cung cấp vị trí cài đặt trong danh mục Windows.");});
