   Find<ComboBox>("ThemeChoice").SelectedIndex=state.Settings.Theme=="Light"?1:0;Find<ComboBox>("FontChoice").SelectedIndex=state.Settings.Font=="Segoe UI Variable"?1:state.Settings.Font=="Calibri"?2:0;Find<ComboBox>("DensityChoice").SelectedIndex=state.Settings.RowHeight==36?0:state.Settings.RowHeight==60?2:1;Find<CheckBox>("MotionChoice").IsChecked=state.Settings.Motion;
   Click("SaveSettings",()=>{state.Settings.Theme=Find<ComboBox>("ThemeChoice").SelectedIndex==1?"Light":"Dark";state.Settings.Font=((ComboBoxItem)Find<ComboBox>("FontChoice").SelectedItem).Content.ToString();state.Settings.RowHeight=new double[]{36,48,60}[Find<ComboBox>("DensityChoice").SelectedIndex];state.Settings.Motion=Find<CheckBox>("MotionChoice").IsChecked==true;state.Save();ApplySettings();BuildHome();BuildPins();Navigate(page);SetStatus("Đã lưu giao diện của bạn.");});
   Find<ListBox>("IndexRoots").ItemsSource=state.Settings.Sources.ToList();
   w.PreviewKeyDown+=Keys;
   w.Closing+=(s,e)=>{if(state.Settings.MinimizeToTray&&!exitRequested){e.Cancel=true;HideToTray();return;}if(jobs.Any(j=>!j.Finished)){if(!Dialog("Tác vụ còn đang chạy","Đóng app và hủy các tác vụ đang chạy? File đã hoàn tất sẽ được giữ lại.",true)){e.Cancel=true;return;}foreach(var j in jobs)j.Cancel();}watching=false;watchTimer.Stop();scan.Cancel();libraryScan.Cancel();state.Save();if(tray!=null)tray.Dispose();};
   SetupUpgrade();ApplySettings();BuildHome();BuildPins();BuildQueries();ready=true;Navigate("Home");return w;
