  void AddWindowButtons(){var root=(Grid)w.Content;var chrome=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top};Grid.SetColumn(chrome,2);chrome.Margin=new Thickness(0,4,6,0);Panel.SetZIndex(chrome,10);
   foreach(string label in new[]{"—","□","×"}){string value=label;var b=new Button {Content=label,Padding=new Thickness(10,2,10,2),Margin=new Thickness(0),FontSize=12,Background=Brushes.Transparent,BorderBrush=Brushes.Transparent};b.Click+=(s,e)=>{if(value=="×")w.Close();else if(value=="—")w.WindowState=WindowState.Minimized;else w.WindowState=w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;};chrome.Children.Add(b);}root.Children.Add(chrome);
   root.PreviewMouseLeftButtonDown+=(s,e)=>{if(e.GetPosition(root).Y<76){DependencyObject node=e.OriginalSource as DependencyObject;while(node!=null&&node!=root){if(node is System.Windows.Controls.Primitives.ButtonBase||node is System.Windows.Controls.Primitives.TextBoxBase)return;node=VisualTreeHelper.GetParent(node);}if(e.ClickCount==2)w.WindowState=w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;else w.DragMove();}};
  }
  void ApplySettings(){w.FontFamily=new FontFamily(state.Settings.Font);foreach(string n in new[]{"FileList","SearchResults","StorageFiles","AppList"})Find<DataGrid>(n).RowHeight=state.Settings.RowHeight;
   bool light=state.Settings.Theme=="Light";var colors=new Dictionary<string,string>{{"Bg",light?"#F4F6FB":"#0D1422"},{"Surface",light?"#FFFFFF":"#141E30"},{"Raised",light?"#E9EEF8":"#1A2740"},{"Border",light?"#D7DEEB":"#25334B"},{"Text",light?"#18243A":"#E7EBF4"},{"Muted",light?"#62718A":"#9CAEC7"}};foreach(var kv in colors)w.Resources[kv.Key]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(kv.Value));w.Background=(Brush)w.Resources["Bg"];w.Foreground=(Brush)w.Resources["Text"];
   w.Resources["Selection"]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#D4E2FA":"#283F66"));
   var fill=new LinearGradientBrush {StartPoint=new Point(0,0),EndPoint=new Point(1,1)};fill.GradientStops.Add(new GradientStop((Color)ColorConverter.ConvertFromString(light?"#F7F9FF":"#263955"),0));fill.GradientStops.Add(new GradientStop((Color)ColorConverter.ConvertFromString(light?"#E4EAF7":"#202944"),1));w.Resources["ButtonFill"]=fill;
  }
  void Navigate(string p){page=p;if(Find<Button>("NavOffice")!=null){Find<Button>("NavOffice").Background=Brushes.Transparent;Find<Button>("NavGames").Background=Brushes.Transparent;}foreach(string name in new[]{"Home","Explorer","Search","Storage","Transfers","Organize","Apps","Settings","Library","Vault"}){Find<FrameworkElement>(name+"Page").Visibility=name==p?Visibility.Visible:Visibility.Collapsed;Find<Button>("Nav"+name).Background=name==p?(state.Settings.Theme=="Light"?new SolidColorBrush(Color.FromRgb(211,225,249)):new SolidColorBrush(Color.FromRgb(30,49,79))):Brushes.Transparent;}
   Find<TextBlock>("PageCrumb").Text=new Dictionary<string,string>{{"Home","Tổng quan"},{"Explorer","Explorer"},{"Search","Tìm kiếm"},{"Storage","Dung lượng"},{"Transfers","Tác vụ"},{"Organize","Phân loại"},{"Apps","Ứng dụng & game"},{"Settings","Cài đặt"},{"Library","Thư viện"},{"Vault","Kho ứng dụng"}}[p];
   if(state.Settings.Motion)Find<Grid>("PageHost").BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0.4,1,TimeSpan.FromMilliseconds(170)));
  }
  TextBlock Text(string value,double size=13,string color=null){var text=new TextBlock {Text=value,FontSize=size,TextWrapping=TextWrapping.Wrap};if(color==null||color=="#9CAEC7")text.SetResourceReference(TextBlock.ForegroundProperty,color==null?"Text":"Muted");else text.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));return text;}
  void BuildHome(){var quick=Find<System.Windows.Controls.Primitives.UniformGrid>("QuickFolders");quick.Children.Clear();var paths=new[]{Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)};var names=new[]{"Tài liệu","Ảnh cá nhân","Downloads","Desktop"};var icons=new[]{"\uE8A5","\uEB9F","\uE896","\uE7F4"};var hues=new[]{"#76CBBE","#B099F0","#84ADFA","#DEBA82"};
   for(int i=0;i<paths.Length;i++){string path=paths[i];var stack=new StackPanel();stack.Children.Add(new TextBlock {Text=icons[i],FontFamily=new FontFamily("Segoe MDL2 Assets"),FontSize=25,Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(hues[i])),Margin=new Thickness(0,0,0,16)});stack.Children.Add(Text(names[i],12));var b=new Button {Content=stack,Padding=new Thickness(16),HorizontalContentAlignment=HorizontalAlignment.Left,Background=(Brush)w.Resources["Surface"]};b.Click+=(s,e)=>OpenFolder(path);quick.Children.Add(b);}
   foreach(var host in new[]{Find<WrapPanel>("DriveCards"),Find<WrapPanel>("StorageDrives")}){host.Children.Clear();foreach(var drive in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed||d.DriveType==DriveType.Removable)){try{if(!drive.IsReady)continue;long total=drive.TotalSize,free=drive.AvailableFreeSpace;string path=drive.RootDirectory.FullName;var stack=new StackPanel();var heading=Text((drive.VolumeLabel.Length>0?drive.VolumeLabel:"Local disk")+"  "+drive.Name,14);heading.FontWeight=FontWeights.SemiBold;stack.Children.Add(heading);stack.Children.Add(new ProgressBar {Value=(total-free)*100.0/total,Height=4,Foreground=new SolidColorBrush(Color.FromRgb(126,165,244)),Background=new SolidColorBrush(Color.FromRgb(42,58,82)),BorderThickness=new Thickness(0),Margin=new Thickness(0,20,0,12)});stack.Children.Add(Text(Fs.Size(free)+" trống / "+Fs.Size(total),11,"#9CAEC7"));var b=new Button {Content=stack,Width=232,Padding=new Thickness(18),Margin=new Thickness(0,0,10,10),Background=(Brush)w.Resources["Surface"]};b.Click+=(s,e)=>OpenFolder(path);host.Children.Add(b);}catch{}}}
   BuildRecents();
  }
  void BuildRecents(){BuildRichRecents();}
  void Recent(string p){p=Fs.Canonical(p);state.Settings.Activity.RemoveAll(x=>Fs.Canonical(x.Path).Equals(p,StringComparison.OrdinalIgnoreCase));state.Settings.Activity.Insert(0,new RecentItem {Path=p,Opened=DateTime.Now});state.Settings.Activity=state.Settings.Activity.Take(60).ToList();state.Settings.Recent.RemoveAll(x=>Fs.Canonical(x).Equals(p,StringComparison.OrdinalIgnoreCase));state.Settings.Recent.Insert(0,p);state.Settings.Recent=state.Settings.Recent.Take(60).ToList();state.Save();BuildRecents();}
  void BuildPins(){var host=Find<StackPanel>("SidebarPins");host.Children.Clear();foreach(var path in state.Settings.Pins.Take(6)){string p=path;var b=new Button {Content="☆  "+Path.GetFileName(p.TrimEnd('\\')),Style=(Style)w.Resources["Nav"],FontSize=11,ToolTip=p};b.Click+=(s,e)=>OpenFolder(p);host.Children.Add(b);}if(host.Children.Count==0){var t=Text("Ghim từ Explorer",10,"#9CAEC7");t.Margin=new Thickness(14,0,0,0);host.Children.Add(t);}}
  string PickFolder(){using(var dialog=new System.Windows.Forms.FolderBrowserDialog {Description="Aster — Chọn thư mục",ShowNewFolderButton=true}){return dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK?dialog.SelectedPath:null;}}
  void BrowseFolder(){string p=PickFolder();if(p!=null)OpenFolder(p);}
  async void OpenFolder(string p){try{p=Path.GetFullPath(p.Trim('"'));if(!Directory.Exists(p))throw new DirectoryNotFoundException("Không tìm thấy thư mục.");if(!historyReplay)navigation.Visit(p);historyReplay=false;UpdateHistoryButtons();folder=p;Find<TextBox>("PathBox").Text=p;Navigate("Explorer");SetStatus("Đang đọc thư mục…");string current=p;var rows=await Task.Run(()=>Fs.List(current));if(folder!=current)return;entries=rows;ApplyExplorerFilter();Find<TextBlock>("FolderStatus").Text=entries.Count+" mục  ·  "+entries.Count(x=>x.IsDirectory)+" thư mục  ·  "+Fs.Size(entries.Sum(x=>x.Bytes));Recent(current);SetStatus("Sẵn sàng · "+current);}catch(Exception e){historyReplay=false;Error(e.Message);}}
  void OpenEntry(Entry f){try{if(f.IsDirectory)OpenFolder(f.Path);else{Process.Start(new ProcessStartInfo(f.Path){UseShellExecute=true});Recent(f.Path);}}catch(Exception e){Error(e.Message);}}
  List<Entry> Selection(){return gridView?Find<ListBox>("FileGrid").SelectedItems.Cast<Entry>().ToList():Find<DataGrid>("FileList").SelectedItems.Cast<Entry>().ToList();}
  async void Details(Entry f){selected=f;Find<Border>("DetailTip").Visibility=f==null?Visibility.Visible:Visibility.Collapsed;Find<Button>("Reveal").IsEnabled=f!=null;Find<Image>("DetailImage").Visibility=Visibility.Collapsed;Find<Image>("DetailImage").Source=null;Find<TextBlock>("DetailGlyph").Visibility=Visibility.Visible;var area=(Grid)Find<Image>("DetailImage").Parent;((Border)area.Parent).Height=f!=null&&f.Kind=="Ảnh"?320:160;Find<Button>("ExpandPhoto").IsEnabled=false;Find<Image>("DetailIcon").Visibility=Visibility.Collapsed;if(f==null){Find<TextBlock>("DetailGlyph").Text="\uF12B";Find<TextBlock>("DetailName").Text="Chọn một mục để xem";Find<TextBlock>("DetailText").Text="Icon ứng dụng, thông tin file và ảnh xem trước sẽ xuất hiện ở đây.";return;}Find<Image>("DetailIcon").Source=f.Icon;Find<Image>("DetailIcon").Visibility=f.Icon==null?Visibility.Collapsed:Visibility.Visible;Find<TextBlock>("DetailGlyph").Visibility=f.Icon==null?Visibility.Visible:Visibility.Collapsed;Find<TextBlock>("DetailGlyph").Text=f.Glyph;Find<TextBlock>("DetailName").Text=f.Name;Find<TextBlock>("DetailText").Text=f.Kind+"\n"+f.Size+"\nSửa đổi: "+f.Date+"\n\n"+f.Path;
   if(f.Kind=="Ảnh"&&f.Bytes<100L*1024*1024){var bitmap=await Task.Run(()=>{try{using(var file=new FileStream(f.Path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=1000;image.StreamSource=file;image.EndInit();image.Freeze();return image;}}catch{return null;}});if(selected==f&&bitmap!=null){Find<Image>("DetailImage").Source=bitmap;Find<Image>("DetailImage").Visibility=Visibility.Visible;Find<Image>("DetailIcon").Visibility=Visibility.Collapsed;Find<TextBlock>("DetailGlyph").Visibility=Visibility.Collapsed;Find<Button>("ExpandPhoto").IsEnabled=true;}}
  }
  async void Queue(string title,string detail,Action<Job> work){var j=new Job {Name=title,Detail=detail,Group=JobGroup(title),Started=DateTime.Now};jobs.Insert(0,j);UpdateJobs();SetStatus(title+" · đang chạy ở nền");await ops.Run(j,()=>work(j));UpdateJobs();SetStatus(title+" · "+j.Status);if(folder.Length>0&&page=="Explorer")OpenFolder(folder);BuildRecents();}
  void TransferSelected(bool move){var paths=Selection().Select(x=>x.Path).ToList();if(paths.Count==0)return;string dest=PickFolder();if(dest!=null)TransferPaths(paths,dest,move);}
  void TransferPaths(List<string> paths,string dest,bool move){Queue((move?"Di chuyển":"Sao chép")+" "+paths.Count+" mục","Từ: "+String.Join(", ",paths.Select(Path.GetDirectoryName).Distinct())+"\nĐến: "+dest,j=>{foreach(var p in paths){j.Check();ops.Transfer(p,Path.Combine(dest,Path.GetFileName(p)),move,j);}});}
  void ValidateName(string name){if(String.IsNullOrWhiteSpace(name)||name=="."||name==".."||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||name.EndsWith(".")||name.EndsWith(" "))throw new IOException("Tên không hợp lệ.");}
  void RenameSelected(){var files=Selection();if(files.Count==0)return;if(files.Count==1){var f=files[0];string name=Prompt("Đổi tên", "Tên mới (bao gồm phần mở rộng)",f.Name);if(name==null||name==f.Name)return;ValidateName(name);string target=Path.Combine(Path.GetDirectoryName(f.Path),name);if(File.Exists(target)||Directory.Exists(target))throw new IOException("Tên này đã tồn tại.");Queue("Đổi tên",f.Name+" → "+name,j=>ops.Transfer(f.Path,target,true,j));}
   else{string prefix=Prompt("Đổi tên hàng loạt","Tiền tố; file sẽ có dạng Tiền tố-001.ext","File");if(prefix==null)return;ValidateName(prefix);Queue("Đổi tên "+files.Count+" mục",prefix,j=>{for(int i=0;i<files.Count;i++){var f=files[i];ops.Transfer(f.Path,Path.Combine(Path.GetDirectoryName(f.Path),prefix+"-"+(i+1).ToString("000")+(f.IsDirectory?"":Path.GetExtension(f.Name))),true,j);}});}}
  void DeleteSelected(){var files=Selection();if(files.Count==0)return;if(!Dialog("Chuyển vào Thùng rác","Chuyển "+files.Count+" mục đã chọn vào Thùng rác?",true))return;Queue("Thùng rác",files.Count+" mục",j=>{foreach(var f in files){j.Check();if(f.IsDirectory)FileSystem.DeleteDirectory(f.Path,UIOption.OnlyErrorDialogs,RecycleOption.SendToRecycleBin,UICancelOption.ThrowException);else FileSystem.DeleteFile(f.Path,UIOption.OnlyErrorDialogs,RecycleOption.SendToRecycleBin,UICancelOption.ThrowException);}});}
  void InstallContext(FrameworkElement target){var menu=new ContextMenu();foreach(var label in new[]{"Mở","Sao chép","Di chuyển","Đổi tên","Thùng rác"}){string action=label;var item=new MenuItem {Header=label};item.Click+=(s,e)=>{try{if(action=="Mở"){var f=Selection().FirstOrDefault();if(f!=null)OpenEntry(f);}else if(action=="Sao chép")TransferSelected(false);else if(action=="Di chuyển")TransferSelected(true);else if(action=="Đổi tên")RenameSelected();else DeleteSelected();}catch(Exception ex){Error(ex.Message);}};menu.Items.Add(item);}target.ContextMenu=menu;}
  void InstallDrag(FrameworkElement target){target.PreviewMouseLeftButtonDown+=(s,e)=>dragStart=e.GetPosition(target);target.MouseMove+=(s,e)=>{var p=e.GetPosition(target);if(e.LeftButton==MouseButtonState.Pressed&&(Math.Abs(p.X-dragStart.X)>8||Math.Abs(p.Y-dragStart.Y)>8)){var paths=Selection().Select(x=>x.Path).ToArray();if(paths.Length>0)DragDrop.DoDragDrop(target,new DataObject(DataFormats.FileDrop,paths),DragDropEffects.Copy);}};target.DragOver+=(s,e)=>{e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};target.Drop+=(s,e)=>{if(folder.Length>0&&e.Data.GetDataPresent(DataFormats.FileDrop)){TransferPaths(((string[])e.Data.GetData(DataFormats.FileDrop)).ToList(),folder,false);e.Handled=true;}};}
  void Keys(object sender,KeyEventArgs e){try{bool ctrl=(Keyboard.Modifiers&ModifierKeys.Control)!=0;bool alt=(Keyboard.Modifiers&ModifierKeys.Alt)!=0;if(ctrl&&e.Key==Key.F){Navigate("Search");Find<TextBox>("SearchText").Focus();e.Handled=true;return;}if(page!="Explorer"||Keyboard.FocusedElement is TextBox)return;if(e.Key==Key.F5){OpenFolder(folder);e.Handled=true;}else if(e.Key==Key.F2){RenameSelected();e.Handled=true;}else if(e.Key==Key.Delete){DeleteSelected();e.Handled=true;}else if(e.Key==Key.Enter){var f=Selection().FirstOrDefault();if(f!=null)OpenEntry(f);e.Handled=true;}else if(alt&&e.Key==Key.Up){var parent=Directory.GetParent(folder);if(parent!=null)OpenFolder(parent.FullName);e.Handled=true;}else if(ctrl&&(e.Key==Key.C||e.Key==Key.X)){internalClipboard=Selection().Select(f=>f.Path).ToList();clipboardMove=e.Key==Key.X;SetStatus(internalClipboard.Count+" mục trong bộ nhớ "+(clipboardMove?"cắt":"sao chép"));e.Handled=true;}else if(ctrl&&e.Key==Key.V){if(internalClipboard.Count>0){TransferPaths(internalClipboard.ToList(),folder,clipboardMove);if(clipboardMove)internalClipboard.Clear();}else if(Clipboard.ContainsFileDropList())TransferPaths(Clipboard.GetFileDropList().Cast<string>().ToList(),folder,false);e.Handled=true;}}catch(Exception ex){Error(ex.Message);}}
  void AddIndex(){string p=PickFolder();if(p==null)return;if(!state.Settings.Sources.Any(x=>x.Equals(p,StringComparison.OrdinalIgnoreCase)))state.Settings.Sources.Add(p);state.Save();Find<ListBox>("IndexRoots").ItemsSource=state.Settings.Sources.ToList();SetStatus("Đã thêm nguồn. Bấm Lập chỉ mục để cập nhật.");}
  async void BuildIndex(){if(state.Settings.Sources.Count==0){AddIndex();if(state.Settings.Sources.Count==0)return;}scan.Cancel();scan=new CancellationTokenSource();var token=scan.Token;var roots=state.Settings.Sources.ToList();Find<TextBlock>("SearchStatus").Text="Đang lập chỉ mục…";try{int skipped=0;var rows=await Task.Run(()=>{var all=new Dictionary<string,Entry>(StringComparer.OrdinalIgnoreCase);foreach(var root in roots)foreach(var f in Fs.Walk(root,token,e=>skipped++)){try{all[f]=Fs.Get(f);}catch{skipped++;}if(all.Count>=50000)return all.Values.ToList();}return all.Values.ToList();});index=rows;FilterSearch();SetStatus("Chỉ mục: "+rows.Count+" file · "+skipped+" mục không truy cập được"+(rows.Count>=50000?" · đã đạt giới hạn 50.000":""));}catch(OperationCanceledException){Find<TextBlock>("SearchStatus").Text="Đã dừng lập chỉ mục.";}catch(Exception e){Error(e.Message);}}
  void ScheduleSearch(){if(!ready)return;searchTimer.Stop();searchTimer.Start();}
  void FilterSearch(){if(!ready)return;string q=Find<TextBox>("SearchText").Text,location=Find<TextBox>("LocationFilter").Text;int type=Find<ComboBox>("TypeFilter").SelectedIndex,size=Find<ComboBox>("SizeFilter").SelectedIndex,date=Find<ComboBox>("DateFilter").SelectedIndex;string kind=type>0?((ComboBoxItem)Find<ComboBox>("TypeFilter").SelectedItem).Content.ToString():null;long min=new long[]{0,10L*1024*1024,100L*1024*1024,1024L*1024*1024}[Math.Max(0,size)];DateTime after=date<=0?DateTime.MinValue:DateTime.Now.AddDays(-new[]{0,7,30,365}[date]);var results=index.Where(f=>f.Name.IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0&&f.Path.IndexOf(location,StringComparison.CurrentCultureIgnoreCase)>=0&&(kind==null||(kind=="Office"?Catalog.Office(f.Path):f.Kind==kind))&&f.Bytes>=min&&f.Modified>=after).ToList();Find<DataGrid>("SearchResults").ItemsSource=results.Take(5000).ToList();Find<TextBlock>("SearchStatus").Text=results.Count+" kết quả / "+index.Count+" file trong chỉ mục"+(results.Count>5000?" · hiển thị 5.000 đầu tiên":"");}
  void BuildQueries(){var host=Find<WrapPanel>("SavedQueries");host.Children.Clear();int n=0;foreach(var preset in state.Settings.Presets){var q=preset;var b=new Button {Content="⌕  "+(String.IsNullOrEmpty(q.Text)?"Bộ lọc "+(++n):q.Text),Padding=new Thickness(10,5,10,5),FontSize=11};b.Click+=(s,e)=>{Find<TextBox>("SearchText").Text=q.Text;Find<TextBox>("LocationFilter").Text=q.Location;Find<ComboBox>("TypeFilter").SelectedIndex=q.Type;Find<ComboBox>("SizeFilter").SelectedIndex=q.Size;Find<ComboBox>("DateFilter").SelectedIndex=q.Date;};host.Children.Add(b);}}
  async void Analyze(bool duplicates){string root=PickFolder();if(root==null)return;scan.Cancel();scan=new CancellationTokenSource();var token=scan.Token;Find<TextBlock>("StorageStatus").Text=(duplicates?"Đang so sánh SHA-256… ":"Đang phân tích… ")+root;
   try{int skipped=0;var all=await Task.Run(()=>{var list=new List<Entry>();foreach(var f in Fs.Walk(root,token,e=>skipped++)){try{list.Add(Fs.Get(f));}catch{skipped++;}}return list;});List<Entry> show=all.OrderByDescending(f=>f.Bytes).Take(100).ToList();int groups=0;
    if(duplicates){show=await Task.Run(()=>{var result=new List<Entry>();foreach(var sizeGroup in all.Where(f=>f.Bytes>0).GroupBy(f=>f.Bytes).Where(g=>g.Count()>1)){var hashes=new Dictionary<string,List<Entry>>();foreach(var f in sizeGroup){token.ThrowIfCancellationRequested();try{using(var input=File.OpenRead(f.Path))using(var sha=System.Security.Cryptography.SHA256.Create()){byte[] b=new byte[1048576];int n;while((n=input.Read(b,0,b.Length))>0){token.ThrowIfCancellationRequested();sha.TransformBlock(b,0,n,b,0);}sha.TransformFinalBlock(new byte[0],0,0);string hash=BitConverter.ToString(sha.Hash);if(!hashes.ContainsKey(hash))hashes[hash]=new List<Entry>();hashes[hash].Add(f);}}catch(IOException){skipped++;}catch(UnauthorizedAccessException){skipped++;}}foreach(var g in hashes.Values.Where(g=>g.Count>1)){groups++;result.AddRange(g);}}return result.OrderByDescending(f=>f.Bytes).ToList();});}
    token.ThrowIfCancellationRequested();storageSnapshot=all;Find<DataGrid>("StorageFiles").ItemsSource=show;var host=Find<StackPanel>("StorageBreakdown");host.Children.Clear();long total=all.Sum(f=>f.Bytes);foreach(var group in all.GroupBy(f=>f.Kind).OrderByDescending(g=>g.Sum(f=>f.Bytes))){long bytes=group.Sum(f=>f.Bytes);var row=new StackPanel {Margin=new Thickness(0,8,0,8)};row.Children.Add(Text(group.Key+"  ·  "+group.Count()+" file  ·  "+Fs.Size(bytes),12));row.Children.Add(new ProgressBar {Height=4,Value=total==0?0:bytes*100.0/total,Foreground=new SolidColorBrush(Color.FromRgb(128,163,238)),Background=new SolidColorBrush(Color.FromRgb(36,51,75)),BorderThickness=new Thickness(0),Margin=new Thickness(0,8,0,0)});host.Children.Add(row);}var folders=Find<StackPanel>("StorageFolders");folders.Children.Clear();foreach(var group in all.GroupBy(f=>{string relative=f.Path.Substring(root.TrimEnd('\\').Length).TrimStart('\\');int slash=relative.IndexOf('\\');return slash<0?"File trực tiếp":relative.Substring(0,slash);}).OrderByDescending(g=>g.Sum(f=>f.Bytes)).Take(8)){var row=Text(group.Key+"  ·  "+Fs.Size(group.Sum(f=>f.Bytes)),12);row.Margin=new Thickness(0,6,0,6);folders.Children.Add(row);}int old=all.Count(f=>f.Modified<DateTime.Now.AddMonths(-6));Find<TextBlock>("StorageStatus").Text=all.Count+" file · "+Fs.Size(total)+" · "+old+" file không sửa hơn 6 tháng · "+skipped+" mục bỏ qua"+(duplicates?" · "+groups+" nhóm trùng nội dung":"")+"\n"+root;
   }catch(OperationCanceledException){Find<TextBlock>("StorageStatus").Text="Đã dừng phân tích.";}catch(Exception e){Error(e.Message);}}
  void InvalidatePlan(){ruleRevision++;plan.Clear();Find<Button>("ApplyRules").IsEnabled=false;if(watching)StopWatch();}
  async void PreviewRules(){Find<DataGrid>("RuleList").CommitEdit(DataGridEditingUnit.Cell,true);Find<DataGrid>("RuleList").CommitEdit(DataGridEditingUnit.Row,true);string source=Find<TextBox>("SourcePath").Text,dest=Find<TextBox>("DestPath").Text;if(!Directory.Exists(source)||String.IsNullOrWhiteSpace(dest)){Error("Chọn thư mục nguồn tồn tại và một thư mục đích.");return;}int revision=ruleRevision;string label=SourceLabel(source,dest);var rules=SnapshotRules();Find<TextBlock>("RuleStatus").Text="Đang kiểm tra file và ngữ cảnh…";try{var result=await Task.Run(()=>Organizer.Plan(source,dest,rules,CancellationToken.None,label));if(revision!=ruleRevision||source!=Find<TextBox>("SourcePath").Text||dest!=Find<TextBox>("DestPath").Text)return;plan=result;Find<DataGrid>("PlanList").ItemsSource=plan;Find<Button>("ApplyRules").IsEnabled=plan.Count>0;Find<TextBlock>("RuleStatus").Text=plan.Count+" file phù hợp. Game, ứng dụng và liên kết hệ thống được bỏ qua.";state.Settings.Destination=dest;state.Save();}catch(Exception e){Error(e.Message);}}
  List<Rule> SnapshotRules(){return state.Settings.Rules.Select(r=>new Rule {Name=r.Name,Extensions=r.Extensions,Enabled=r.Enabled}).ToList();}
  string SourceLabel(string source,string dest){string prefix=Path.GetFullPath(dest).TrimEnd('\\').ToLowerInvariant()+"|",key=prefix+Path.GetFullPath(source).TrimEnd('\\').ToLowerInvariant();string label;if(state.Settings.SourceBuckets.TryGetValue(key,out label))return label;string name=Path.GetFileName(source.TrimEnd('\\'));var used=state.Settings.SourceBuckets.Where(k=>k.Key.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)).Select(k=>k.Value).ToList();label=name;int i=2;while(used.Any(s=>s.Equals(label,StringComparison.OrdinalIgnoreCase)))label=name+" ("+(i++)+")";state.Settings.SourceBuckets[key]=label;state.Save();return label;}
  void ToggleWatch(){if(watching){StopWatch();return;}string source=Find<TextBox>("SourcePath").Text,dest=Find<TextBox>("DestPath").Text;if(!Directory.Exists(source)||String.IsNullOrWhiteSpace(dest)){Error("Chọn nguồn và đích trước khi bật tự động.");return;}watchLabel=SourceLabel(source,dest);Organizer.Plan(source,dest,SnapshotRules(),CancellationToken.None,watchLabel);watchSource=source;watchDest=dest;watchRuleSet=SnapshotRules();stable.Clear();watching=true;watchTimer.Start();Find<Button>("WatchRules").Content="Tắt tự động";Find<TextBlock>("RuleStatus").Text="Đang theo dõi nguồn: "+source+". File ổn định sẽ được phân loại mỗi 8 giây.";SetStatus("Tự động đang bật · "+source);state.Settings.Destination=dest;state.Save();}
  void StopWatch(){watching=false;watchTimer.Stop();Find<Button>("WatchRules").Content="Bật tự động cho nguồn này";Find<TextBlock>("RuleStatus").Text="Tự động đã tắt. Cấu hình đã thay đổi cần được xem trước lại.";}
  async void WatchTick(){if(!watching||watchBusy)return;watchBusy=true;string source=watchSource,dest=watchDest,label=watchLabel;var rules=watchRuleSet;try{var candidates=await Task.Run(()=>Organizer.Plan(source,dest,rules,CancellationToken.None,label));if(!watching||source!=watchSource||dest!=watchDest)return;var eligible=new List<PlanItem>();var present=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var item in candidates){try{var f=new FileInfo(item.Source);present.Add(item.Source);string key=f.Length+"/"+f.LastWriteTimeUtc.Ticks;string previous;if(stable.TryGetValue(item.Source,out previous)&&previous==key&&f.LastWriteTimeUtc<DateTime.UtcNow.AddSeconds(-10)){using(var test=new FileStream(item.Source,FileMode.Open,FileAccess.Read,FileShare.None)){}eligible.Add(item);}stable[item.Source]=key;}catch(IOException){}}foreach(var key in stable.Keys.Where(k=>!present.Contains(k)).ToList())stable.Remove(key);if(eligible.Count>0){var j=new Job {Name="Tự động phân loại "+eligible.Count+" file",Detail=source,Group="Phân loại",Started=DateTime.Now};jobs.Insert(0,j);await ops.Run(j,()=>ops.Organize(eligible,j));UpdateJobs();SetStatus(j.Name+" · "+j.Status);if(j.Status.StartsWith("Lỗi")){StopWatch();Error("Tự động đã dừng: "+j.Status);}foreach(var item in eligible)stable.Remove(item.Source);}}catch(Exception e){StopWatch();Error(e.Message);}finally{watchBusy=false;}}
  async void LoadApps(){SetStatus("Đang đọc danh mục ứng dụng…");apps=await Task.Run(()=>{var result=new Dictionary<string,InstalledApp>(StringComparer.OrdinalIgnoreCase);foreach(var hive in new[]{RegistryHive.LocalMachine,RegistryHive.CurrentUser})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})try{using(var root=RegistryKey.OpenBaseKey(hive,view))using(var uninstall=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){if(uninstall==null)continue;foreach(var name in uninstall.GetSubKeyNames())using(var k=uninstall.OpenSubKey(name)){if(k==null)continue;string display=k.GetValue("DisplayName") as string;if(String.IsNullOrWhiteSpace(display))continue;string location=k.GetValue("InstallLocation") as string??"",publisher=k.GetValue("Publisher") as string??"";string lower=(display+" "+location+" "+publisher).ToLowerInvariant();result[display]=new InstalledApp {Name=display,Publisher=publisher,Location=location,UninstallCommand=k.GetValue("UninstallString") as string,IconPath=IconFile(k.GetValue("DisplayIcon") as string),LaunchPath=LaunchCandidate(k.GetValue("DisplayIcon") as string),Group=lower.Contains("steam")||lower.Contains("epic games")||lower.Contains("riot")||lower.Contains("gog")?"Game / launcher":"Ứng dụng"};}}}catch{}return result.Values.OrderBy(a=>a.Name).ToList();});foreach(var shortcut in state.Settings.Shortcuts){apps.RemoveAll(a=>a.Name==shortcut.Name);apps.Add(new InstalledApp {Name=shortcut.Name,IconPath=shortcut.Path,Location=Path.GetDirectoryName(shortcut.Path),LaunchPath=shortcut.Path,Publisher="Shortcut của bạn",Group=shortcut.Group});}foreach(var item in apps){string group;if(state.Settings.AppGroups.TryGetValue(item.Name,out group))item.Group=group;}apps=apps.OrderBy(a=>a.Group).ThenBy(a=>a.Name).ToList();Find<DataGrid>("AppList").ItemsSource=apps;SetStatus(apps.Count+" ứng dụng trong danh mục Win32 · nhóm game dựa trên tên và đường dẫn");}
  void LaunchApp(){var item=Find<DataGrid>("AppList").SelectedItem as InstalledApp;if(item==null)return;if(String.IsNullOrEmpty(item.LaunchPath)||!File.Exists(item.LaunchPath)){Error("Thêm shortcut (.lnk) hoặc file .exe của ứng dụng để mở từ Aster.");return;}Process.Start(new ProcessStartInfo(item.LaunchPath){UseShellExecute=true});}
  void AddShortcut(){var dialog=new OpenFileDialog {Title="Thêm ứng dụng hoặc game",Filter="Ứng dụng và shortcut|*.exe;*.lnk;*.url"};if(dialog.ShowDialog(w)!=true)return;var shortcut=new AppShortcut {Name=Path.GetFileNameWithoutExtension(dialog.FileName),Path=dialog.FileName,Group="Ứng dụng"};state.Settings.Shortcuts.Add(shortcut);state.Save();LoadApps();}
  Window Modal(string title){var dialog=new Window {Title=title,Width=540,Height=330,Owner=w,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize,WindowStyle=WindowStyle.None,Background=(Brush)w.Resources["Bg"],Foreground=(Brush)w.Resources["Text"],FontFamily=w.FontFamily,FontSize=13};dialog.Resources=w.Resources;return dialog;}
  bool Dialog(string title,string message,bool confirm){var d=Modal(title);var stack=new DockPanel {Margin=new Thickness(26)};var heading=Text(title,22);heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,0,0,20);DockPanel.SetDock(heading,Dock.Top);stack.Children.Add(heading);var buttons=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,20,0,0)};DockPanel.SetDock(buttons,Dock.Bottom);var ok=new Button {Content=confirm?"Xác nhận":"Đóng",Background=new SolidColorBrush(Color.FromRgb(82,123,208))};ok.Click+=(s,e)=>{d.DialogResult=true;};if(confirm){var cancel=new Button {Content="Hủy"};cancel.Click+=(s,e)=>d.DialogResult=false;buttons.Children.Add(cancel);}buttons.Children.Add(ok);stack.Children.Add(buttons);stack.Children.Add(new ScrollViewer {Content=Text(String.IsNullOrEmpty(message)?"Chưa có dữ liệu.":message,12,"#9CAEC7")});d.Content=stack;return d.ShowDialog()==true;}
  string Prompt(string title,string hint,string initial){var d=Modal(title);d.Height=270;var stack=new StackPanel {Margin=new Thickness(26)};stack.Children.Add(Text(title,22));var t=Text(hint,12,"#9CAEC7");t.Margin=new Thickness(0,14,0,14);stack.Children.Add(t);var input=new TextBox {Text=initial};stack.Children.Add(input);var buttons=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,22,0,0)};var cancel=new Button {Content="Hủy"};cancel.Click+=(s,e)=>d.DialogResult=false;var ok=new Button {Content="Lưu",IsDefault=true};ok.Click+=(s,e)=>d.DialogResult=true;buttons.Children.Add(cancel);buttons.Children.Add(ok);stack.Children.Add(buttons);d.Content=stack;d.Loaded+=(s,e)=>{input.Focus();input.SelectAll();};return d.ShowDialog()==true?input.Text:null;}
  public void Render(string path,string p){Navigate(p);w.WindowState=WindowState.Normal;w.Width=1440;w.Height=900;var root=(FrameworkElement)w.Content;root.BeginAnimation(UIElement.OpacityProperty,null);Find<Grid>("PageHost").BeginAnimation(UIElement.OpacityProperty,null);Find<Grid>("PageHost").Opacity=1;root.Measure(new Size(1440,900));root.Arrange(new Rect(0,0,1440,900));root.UpdateLayout();var bitmap=new RenderTargetBitmap(1440,900,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(path))encoder.Save(file);}
 }
 public static class Program {
  [STAThread] public static int Main(string[] args){try{var app=new Application();string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aster");if(args.Length>1&&args[0]=="--render")data=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[1])),"preview-state");var desktop=new Desktop(data);var window=desktop.Create();if(args.Length>1&&args[0]=="--render"){desktop.Render(args[1],args.Length>2?args[2]:"Home");return 0;}if(args.Contains("--tray"))window.Loaded+=(s,e)=>desktop.HideToTray();app.Run(window);return 0;}catch(Exception e){string log=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"startup-error.log");try{File.WriteAllText(log,e.ToString());}catch{}return 1;}}
 }
